import{_ as s,C as a,o as l,c as d,j as e,a as c,E as r,a6 as o}from"./chunks/framework.CD0vXS2f.js";const v=JSON.parse('{"title":"01 · Executive Thesis & AI Data Plane Architecture","description":"Architectural thesis for unifying Microsoft Fabric / OneLake & Fabric IQ, Microsoft Purview DSPM for AI, Azure Cosmos DB DiskANN vector/hybrid search, and Azure AI Search Foundry IQ into an enterprise AI data plane.","frontmatter":{"title":"01 · Executive Thesis & AI Data Plane Architecture","description":"Architectural thesis for unifying Microsoft Fabric / OneLake & Fabric IQ, Microsoft Purview DSPM for AI, Azure Cosmos DB DiskANN vector/hybrid search, and Azure AI Search Foundry IQ into an enterprise AI data plane."},"headers":[],"relativePath":"playbooks/ai-data-strategy/01-executive-thesis.md","filePath":"playbooks/ai-data-strategy/01-executive-thesis.md","lastUpdated":1795642852816,"verifiedStamp":"2026-11-25 13:40 PST"}'),g={name:"playbooks/ai-data-strategy/01-executive-thesis.md"};function u(h,t,f,p,y,b){const i=a("PlaybookMeta"),n=a("PageBrief");return l(),d("div",null,[t[0]||(t[0]=e("h1",{id:"_01-·-executive-thesis-ai-data-plane-architecture",tabindex:"-1"},[c("01 · Executive Thesis & AI Data Plane Architecture "),e("a",{class:"header-anchor",href:"#_01-·-executive-thesis-ai-data-plane-architecture","aria-label":'Permalink to "01 · Executive Thesis & AI Data Plane Architecture"'},"​")],-1)),r(i,{track:"05 · AI Data Strategy, Fabric–Foundry & Governance",provenance:"Customer-Zero Validated (Enterprise Multi-Source Grounding, Analytics & Regulated Agent Data Plane)",governance:"Sanitized · Peer Reviewed · IP Screened",owners:"John Luo (@jluocsa) · Co-Authors Welcome",verified:"2026-11-23 19:30 PST",status:"Live v2.0",paperHref:"/papers/enterprise-foundry-platform-blueprint",paperLabel:"Full-Stack Blueprint →",studioHref:"/studio/#data-strategy",studioLabel:"Data Strategy Advisor →",kitHref:"/papers/engineering-kits#data-gate",kitLabel:"data_readiness_gate.py →"}),r(n,{stage:"start",readTime:"5 min read",problem:"Even when PTU sizing, APIM spillover, regional BCP, and ACA sandboxes are rock-solid, enterprise AI programs stall when unstructured RAG indexes, Fabric BI semantics, Cosmos DB agent memory, and Purview security labels drift apart.",takeaway:"Treat the AI Data Plane as a governed three-store architecture—Microsoft Fabric / OneLake & Fabric IQ for structured/analytical truth, Azure AI Search (Foundry IQ) for unstructured corpus retrieval, and Azure Cosmos DB (DiskANN + RRF hybrid) for tenant-isolated operational memory—unified under Microsoft Purview DSPM for AI and gated by D1–D12.",csaUse:"Walk through the 5-stage AI Data Plane diagram and four failure modes below during discovery with CDO, Data Platform, Security, and AI Engineering leads."}),t[1]||(t[1]=o('<h2 id="four-structural-failure-modes-at-the-ai-data-plane" tabindex="-1">Four Structural Failure Modes at the AI Data Plane <a class="header-anchor" href="#four-structural-failure-modes-at-the-ai-data-plane" aria-label="Permalink to &quot;Four Structural Failure Modes at the AI Data Plane&quot;">​</a></h2><p>Playbooks 01–04 stabilize <strong>inference economics, gateway resiliency, multi-region failover, and sandboxed agent execution</strong>. Yet in production enterprise rollouts, <strong>70%+ of late-stage security holds and grounding regressions originate upstream in the data plane</strong>:</p><ol><li><strong>Structured vs. Unstructured Split-Brain:</strong> Teams dump tabular ERP exports, financial KPIs, and Power BI tables as flat CSV chunks into a vector database—producing hallucinated aggregations and stale numbers. Conversely, unstructured regulatory PDFs cannot be queried cleanly via SQL. Production platforms route <strong>structured/semantic questions to Microsoft Fabric IQ</strong> (<code>OneLake</code> + Semantic Models + Fabric Data Agents) and <strong>unstructured prose/tables to Azure AI Search (<code>Foundry IQ</code>)</strong> <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>.</li><li><strong>Oversharing, Label Stripping &amp; Stale ACL Revocation:</strong> Ingestion pipelines frequently copy SharePoint or OneLake files into blob staging and strip <strong>Microsoft Purview sensitivity labels</strong> and <strong>Entra ID group ACLs</strong>. Even when ACLs are indexed at ingestion time, relying on nightly batch crawlers leaves revoked users able to retrieve confidential engagement documents for hours—violating ethical-wall mandates <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>.</li><li><strong>Immutable Vector Policies &amp; Re-Embedding Cliffs:</strong> In <strong>Azure Cosmos DB for NoSQL</strong>, vector policies and <code>DiskANN</code> vector indexes are immutable after container creation <span class="ev-badge ev-m">[M]</span>. Likewise, upgrading embedding models or chunking strategies across millions of Azure AI Search chunks without blue-green index aliases and embedding TPM quota math triggers prolonged search outages or <code>HTTP 429</code> ingestion stalls <span class="ev-badge ev-arch">[Arch]</span>.</li><li><strong>Silent Corpus Drift, Prompt Poisoning &amp; Disconnected Evals:</strong> Unvalidated document uploads can inject hidden indirect prompt-injection instructions into vector stores, while production <code>gen_ai.*</code> failure traces never flow back into OneLake Gold evaluation sets—leaving retrieval precision decaying silently over quarters <span class="ev-badge ev-arch">[Arch]</span> <span class="ev-badge ev-agree">[Agree]</span>.</li></ol>',3)),t[2]||(t[2]=e("div",{class:"arch-diagram"},[e("svg",{viewBox:"0 0 760 192",role:"img","aria-labelledby":"pb5-t1-title pb5-t1-desc","font-family":"Segoe UI, Inter, -apple-system, sans-serif"},[e("title",{id:"pb5-t1-title"},"Enterprise AI Data Plane: Fabric OneLake, Purview DSPM, Cosmos DB Hybrid & Foundry IQ"),e("desc",{id:"pb5-t1-desc"},"Shows 1 OneLake Medallion & Shortcuts feeding Fabric IQ structured analytics, 2 Content Understanding & Anti-Poisoning ingestion, 3 Three-Store Grounding Layer (Fabric IQ, AI Search Foundry IQ, Cosmos DB DiskANN Hybrid), 4 Microsoft Purview DSPM for AI Governance & ACL Tombstoning spanning all layers, and 5 Foundry Agents + OTel-to-Fabric Eval Flywheel gated by D1-D12."),e("defs",null,[e("marker",{id:"ds-arr",markerWidth:"8",markerHeight:"8",refX:"7",refY:"4",orient:"auto"},[e("path",{d:"M0 0 L8 4 L0 8Z",fill:"#0f766e"})])]),e("rect",{x:"8",y:"10",width:"744",height:"30",rx:"6",fill:"#fff7eb",stroke:"#d97706","stroke-width":"1.4"}),e("text",{x:"20",y:"29","font-size":"8.6","font-weight":"700",fill:"#92400e"},"MICROSOFT PURVIEW DSPM FOR AI · Sensitivity Label Inheritance · Oversharing Scans · Entra ACL Tombstoning (≤15m / ≤5m) · Prompt Audit"),e("rect",{x:"8",y:"52",width:"136",height:"106",rx:"6",fill:"#edf3fb",stroke:"#5b87b2","stroke-width":"1.4"}),e("text",{x:"16",y:"71","font-size":"9.0","font-weight":"700",fill:"#183e62"},"1. OneLake & Sources"),e("text",{x:"16",y:"87","font-size":"8.0",fill:"#334e68"},"• Zero-copy Shortcuts"),e("text",{x:"16",y:"101","font-size":"8.0",fill:"#334e68"},"• Bronze → AI Gold"),e("text",{x:"16",y:"115","font-size":"8.0",fill:"#334e68"},"• SharePoint / ADLS"),e("text",{x:"16",y:"140","font-size":"7.7","font-weight":"700",fill:"#1d4ed8"},"[Lineage SHA-256]"),e("path",{d:"M144 105 H162",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#ds-arr)"}),e("rect",{x:"166",y:"52",width:"142",height:"106",rx:"6",fill:"#edf3fb",stroke:"#5b87b2","stroke-width":"1.4"}),e("text",{x:"174",y:"71","font-size":"9.0","font-weight":"700",fill:"#183e62"},"2. Ingestion & Hygiene"),e("text",{x:"174",y:"87","font-size":"8.0",fill:"#334e68"},"• Content Understanding"),e("text",{x:"174",y:"101","font-size":"8.0",fill:"#334e68"},"• Layout-aware chunks"),e("text",{x:"174",y:"115","font-size":"8.0",fill:"#334e68"},"• Injection sanitizer"),e("text",{x:"174",y:"140","font-size":"7.7","font-weight":"700",fill:"#1d4ed8"},"[Label + ACL Stamp]"),e("path",{d:"M308 105 H326",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#ds-arr)"}),e("rect",{x:"330",y:"52",width:"154",height:"106",rx:"6",fill:"#eaf7f5",stroke:"#0f766e","stroke-width":"1.5"}),e("text",{x:"338",y:"71","font-size":"9.0","font-weight":"700",fill:"#115e59"},"3. Three-Store Serving"),e("text",{x:"338",y:"87","font-size":"8.0",fill:"#334e68"},"• Fabric IQ (Structured)"),e("text",{x:"338",y:"101","font-size":"8.0",fill:"#334e68"},"• AI Search (Foundry IQ)"),e("text",{x:"338",y:"115","font-size":"8.0",fill:"#334e68"},"• Cosmos DiskANN + RRF"),e("text",{x:"338",y:"140","font-size":"7.7","font-weight":"700",fill:"#0f766e"},"[Alias & Partition Guard]"),e("path",{d:"M484 105 H502",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#ds-arr)"}),e("rect",{x:"506",y:"52",width:"118",height:"106",rx:"6",fill:"#f5f3ff",stroke:"#7c3aed","stroke-width":"1.5"}),e("text",{x:"514",y:"71","font-size":"9.0","font-weight":"700",fill:"#5b21b6"},"4. Foundry Agents"),e("text",{x:"514",y:"87","font-size":"8.0",fill:"#334e68"},"• Dual-path tool route"),e("text",{x:"514",y:"101","font-size":"8.0",fill:"#334e68"},"• Pos 6 cache-safe tail"),e("text",{x:"514",y:"115","font-size":"8.0",fill:"#334e68"},"• Zero-trust RBAC"),e("text",{x:"514",y:"140","font-size":"7.7","font-weight":"700",fill:"#6d28d9"},"[Grounded Context]"),e("path",{d:"M624 105 H642",stroke:"#0f766e","stroke-width":"1.8","marker-end":"url(#ds-arr)"}),e("rect",{x:"646",y:"52",width:"106",height:"106",rx:"6",fill:"#eaf4f5",stroke:"#0f766e","stroke-width":"1.5"}),e("text",{x:"654",y:"71","font-size":"9.0","font-weight":"700",fill:"#115e59"},"5. Data Flywheel"),e("text",{x:"654",y:"87","font-size":"8.0",fill:"#334e68"},"• DRG001–007 CLI"),e("text",{x:"654",y:"101","font-size":"8.0",fill:"#334e68"},"• Freshness KQL"),e("text",{x:"654",y:"115","font-size":"8.0",fill:"#334e68"},"• Gold Eval Lake"),e("text",{x:"654",y:"140","font-size":"7.7","font-weight":"700",fill:"#0f766e"},"[D1–D12 Signed]"),e("text",{x:"10",y:"178","font-size":"8.3",fill:"#526c80"},"Unified AI Data Plane bridging Playbook 01 (Pos 6 caching), Playbook 03 (regional stamp sync), and Playbook 04 (Foundry IQ + Evals).")])],-1)),t[3]||(t[3]=o('<hr><h2 id="how-playbook-05-interlocks-with-playbooks-01–04" tabindex="-1">How Playbook 05 Interlocks With Playbooks 01–04 <a class="header-anchor" href="#how-playbook-05-interlocks-with-playbooks-01–04" aria-label="Permalink to &quot;How Playbook 05 Interlocks With Playbooks 01–04&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Upstream / Downstream Track</th><th style="text-align:left;">Architectural Seam Governed by Playbook 05</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="/enterprise-azure-ai-hub/playbooks/prompt-caching/start/01-executive-thesis">Playbook 01 · Prompt Caching &amp; PTU</a></strong></td><td style="text-align:left;">Deterministic chunk ordering and canonical citation payloads placed strictly in <strong>Position 6</strong> preserve <code>Pos 1–3</code> <code>T0</code> prefix reuse; Regulated <code>Posture A</code> ethical walls align directly with Purview sensitivity labels and Cosmos DB tenant partition keys (<code>D5</code>, <code>D11</code>).</td></tr><tr><td style="text-align:left;"><strong><a href="/enterprise-azure-ai-hub/playbooks/apim-gateway/01-executive-thesis">Playbook 02 · APIM AI Gateway</a></strong></td><td style="text-align:left;">Embedding re-indexing pipelines route through dedicated batch APIM quotas so a 5-million-chunk re-embedding backfill never starves interactive user inference PTUs (<code>D8</code>).</td></tr><tr><td style="text-align:left;"><strong><a href="/enterprise-azure-ai-hub/playbooks/multi-region-bcp/01-executive-thesis">Playbook 03 · Multi-Region BCP</a></strong></td><td style="text-align:left;">Dual-region Azure AI Search stamps fed from <code>RA-GZRS</code> ADLS / OneLake plus multi-region <strong>Cosmos DB DiskANN + RRF</strong> containers keep grounding lag <code>&lt;1%</code> across regional failovers (<code>D7</code>, <code>D11</code>).</td></tr><tr><td style="text-align:left;"><strong><a href="/enterprise-azure-ai-hub/playbooks/agentic-rag-evals/01-executive-thesis">Playbook 04 · Agentic RAG &amp; Evals</a></strong></td><td style="text-align:left;">Extends <code>knowledge_base_retrieve</code> (Foundry IQ MCP) with <strong>Fabric IQ</strong> structured analytics, <strong>Purview DSPM</strong> label inheritance, <strong>Cosmos DB</strong> episodic memory, and an OTel-to-OneLake Gold eval dataset flywheel (<code>D1</code>, <code>D12</code>).</td></tr></tbody></table><hr><h2 id="core-engineering-questions-answered-in-playbook-05" tabindex="-1">Core Engineering Questions Answered in Playbook 05 <a class="header-anchor" href="#core-engineering-questions-answered-in-playbook-05" aria-label="Permalink to &quot;Core Engineering Questions Answered in Playbook 05&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Question</th><th style="text-align:left;">Verified Architectural Answer</th><th style="text-align:left;">Chapter</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>How do we connect Microsoft Fabric &amp; OneLake to Microsoft Foundry agents without duplicating petabytes or throttling BI capacities?</strong></td><td style="text-align:left;">Federate data with <strong>OneLake Shortcuts</strong>, expose curated semantic models &amp; Lakehouse tables via <strong>Fabric IQ / Fabric Data Agents</strong>, index unstructured OneLake Files via Azure AI Search Shared Private Link, and isolate interactive AI-serving <strong>F-SKU</strong> capacities from nightly Spark batch refresh capacities <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>.</td><td style="text-align:left;"><a href="./02-fabric-onelake-fabric-iq">02 · Fabric, OneLake &amp; Fabric IQ</a></td></tr><tr><td style="text-align:left;"><strong>How do we prevent AI oversharing, preserve Purview sensitivity labels, and enforce ethical-wall access revocations in minutes instead of days?</strong></td><td style="text-align:left;">Activate <strong>Microsoft Purview DSPM for AI</strong> across Foundry &amp; Fabric, stamp Purview sensitivity labels + Entra <code>acl_group_ids</code> into every chunk/document at ingestion, and wire an event-driven tombstone queue enforcing <code>&lt;=15 min</code> (<code>&lt;=5 min</code> regulated) revocation propagation <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>.</td><td style="text-align:left;"><a href="./03-purview-dspm-acl-ethical-walls">03 · Purview DSPM, Labels &amp; Ethical Walls</a></td></tr><tr><td style="text-align:left;"><strong>When should we use Azure Cosmos DB Vector/Hybrid (<code>DiskANN</code> + <code>RRF</code>) vs. Azure AI Search vs. Fabric IQ—and how do we avoid re-embedding outages?</strong></td><td style="text-align:left;">Use <strong>Cosmos DB DiskANN + BM25 RRF</strong> for tenant-partitioned operational RAG and agent memory, <strong>Azure AI Search + Foundry IQ</strong> for multi-document corpus reranking, and <strong>Fabric IQ</strong> for analytical KPIs; enforce blue-green container/alias cutovers because Cosmos DB vector policies are immutable after creation <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>.</td><td style="text-align:left;"><a href="./04-cosmos-vector-hybrid-retrieval">04 · Cosmos DB Vector/Hybrid &amp; Retrieval</a></td></tr><tr><td style="text-align:left;"><strong>How do we gate AI data readiness automatically in CI/CD and monitor freshness/poisoning drift in production?</strong></td><td style="text-align:left;">Enforce <code>D1–D12</code> using the zero-dependency <strong><code>data_readiness_gate.py</code></strong> CLI (<code>DRG001–DRG007</code>) in PR/release pipelines and deploy <strong><code>data-grounding-freshness-gate.kql</code></strong> in Azure Monitor.</td><td style="text-align:left;"><a href="./05-data-governance-release-gates">05 · D1–D12 Gates &amp; Automation</a></td></tr></tbody></table>',6))])}const x=s(g,[["render",u]]);export{v as __pageData,x as default};
